import{_ as t,o,c as i,a5 as l}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"寄生组合式继承","description":"思路： 对于父类实例非共享属性，我们通过构造器借用的方式复制； 所以，设置子类原型时不必调用超类的构造函数创建超类实例，因为超类实例的非共享属性，会用构造器借用的方式来复制； 所以我们只要子类原型对象原型式继承父类原型对象即可； 这样子类实例即有了父类实例的非共享属性，又通过原型。","frontmatter":{"title":"寄生组合式继承","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","对象、数组与函数"],"description":"思路： 对于父类实例非共享属性，我们通过构造器借用的方式复制； 所以，设置子类原型时不必调用超类的构造函数创建超类实例，因为超类实例的非共享属性，会用构造器借用的方式来复制； 所以我们只要子类原型对象原型式继承父类原型对象即可； 这样子类实例即有了父类实例的非共享属性，又通过原型。","sidebarWeight":151,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/面向对象程序设计/(80m)继承/(10m)寄生组合式继承.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(10m)寄生组合式继承.md","filePath":"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(10m)寄生组合式继承.md"}'),r={name:"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(10m)寄生组合式继承.md"};function a(n,e,p,s,c,u){return o(),i("div",null,[...e[0]||(e[0]=[l('<div><h1 id="寄生组合式继承" tabindex="-1">寄生组合式继承 <a class="header-anchor" href="#寄生组合式继承" aria-label="Permalink to &quot;寄生组合式继承&quot;">​</a></h1><blockquote><p>本节目标：理解“寄生组合式继承”的核心思路，并能把它用于实际开发或面试表达。 <strong>思路：</strong></p></blockquote><ul><li>对于父类实例非共享属性，我们通过构造器借用的方式复制；</li><li>所以，设置子类原型时不必调用超类的构造函数创建超类实例，因为超类实例的非共享属性，会用构造器借用的方式来复制；</li><li>所以我们只要子类原型对象原型式继承父类原型对象即可；</li><li>这样子类实例即有了父类实例的非共享属性，又通过原型链继承得到了父类实例的共享属性。</li></ul><p>寄生组合式继承的基本模式如下：参数为两个构造函数 function inheritPrototype(subType, superType) { <a href="//1.xn--4gqvd70lxjr4ce6ktqoy3p7r6ahqm5g8b" target="_blank" rel="noreferrer">//1.创建超类原型的一个副本</a> var prototype = object(superType.prototype); <a href="//2.xn--constructor-xm8r49bsyl9t5a2qcdybm40bt1mxwl57i11b760ot63agw6h" target="_blank" rel="noreferrer">//2.将副本的constructor属性指向子类构造函数</a> // 可以为原型添加其它属性和方法 prototype.constructor = subType; <a href="//3.xn--vnq80fhhy5bkq10o7rhupbuzn6rijxc7vtys2cia900u" target="_blank" rel="noreferrer">//3.将子类的原型指向我们创建的副本</a> subType.prototype = prototype; }</p><p>具体实现如下：</p><ol><li>先定义两个构造函数，其中子类构造函数借用父类构造函数，并在执行父类构造函数后，添加子类实例特有的属性；</li><li>再执行寄生组合式继承；</li><li>再为子类原型添加属性或方法；</li></ol><p><strong>执行过程：</strong></p><ul><li>子类原型对象原型式继承父类原型对象；</li><li>定义子类原型对象特有的属性或方法；</li><li>使用new创建子类实例，在子类执行环境下执行父类构造函数；</li><li>定义子类实例特有的属性和方法</li></ul><p>function SuperType(name) { this.name = name; this.colors = [&#39;red&#39;, &#39;blue&#39;, &#39;green&#39;] } SuperType.prototype.sayName = function () { console.log(this.name); } function SubType(name, age) { SuperType.call(this.name); this.age = age; } inheritPrototype(SubType, SuperType); SubType.prototype.sayAge = function () { console.log(age); }</p><p>这个例子的高效率体现在：</p><ol><li>它只调用了一次SuperType构造函数；</li><li>且避免了在SubType.prototype上面创建不必要的，多余的属性。</li><li>与此同时，原型链还能保持不变；因此还能够正常使用instanceof 和isPrototypeOf。</li></ol><p>开发人员普遍认为寄生组合式继承是引用类型最理想的继承范式。 YUI的YAHOO.lang.extend()方法采用了寄生组合式继承，从而让这种模式首次出现在了一个应用非常广泛的Javascript库中。</p><p>寄生组合式继承（Parasitic Combination Inheritance）是 JavaScript 中一种非常有效和实用的继承方式，它结合了构造函数继承和原型链继承的优点，同时避免了组合继承的一些缺点。它通过使用寄生式继承来减少重复调用父类构造函数，从而提高性能和内存利用率。</p><p>实现方法 寄生组合式继承的关键在于以下几点：</p><ul><li>通过构造函数继承父类的实例属性。</li><li>通过寄生式继承继承父类的原型属性。</li></ul><p>示例代码 下面是一个使用寄生组合式继承实现继承的示例： // 父类构造函数 function Parent(name) { this.name = name; this.colors = [&#39;red&#39;, &#39;blue&#39;, &#39;green&#39;]; } // 父类原型方法 Parent.prototype.sayName = function() { console.log(this.name); }; // 子类构造函数 function Child(name, age) { Parent.call(this, name); // 继承父类属性 this.age = age; } // 寄生式继承父类原型 function inheritPrototype(child, parent) { let prototype = Object.create(parent.prototype); // 创建父类原型的副本 prototype.constructor = child; // 修正 constructor 指向 child.prototype = prototype; // 将副本赋值给子类原型 } inheritPrototype(Child, Parent); Child.prototype.sayAge = function() { console.log(this.age); }; // 测试寄生组合式继承 let instance1 = new Child(&#39;Alice&#39;, 25); instance1.colors.push(&#39;black&#39;); console.log(instance1.colors); // 输出: [&#39;red&#39;, &#39;blue&#39;, &#39;green&#39;, &#39;black&#39;] instance1.sayName(); // 输出: Alice instance1.sayAge(); // 输出: 25 let instance2 = new Child(&#39;Bob&#39;, 30); console.log(instance2.colors); // 输出: [&#39;red&#39;, &#39;blue&#39;, &#39;green&#39;] instance2.sayName(); // 输出: Bob instance2.sayAge(); // 输出: 30</p><p>详细解释</p><ul><li>构造函数继承： <ul><li>在子类构造函数 Child 中，使用 Parent.call(this, name) 调用父类构造函数，继承父类的实例属性。</li></ul></li><li>寄生式继承父类原型： <ul><li>使用 Object.create(parent.prototype) 创建父类原型的副本。</li><li>修正副本的 constructor 指向子类构造函数。</li><li>将这个副本赋值给子类的原型。</li></ul></li><li>修复构造函数指向： <ul><li>由于寄生式继承会创建一个新的对象副本，所以需要修正这个副本的 constructor 属性指向子类构造函数。</li></ul></li></ul><p>优点</p><ul><li>性能优化：避免了在子类原型上直接创建父类实例的重复调用，减少了不必要的性能开销。</li><li>原型链共享：通过原型链共享方法，实现了高效的原型继承。</li><li>独立的实例属性：每个子类实例都有自己的属性副本，不会共享父类的实例属性，避免了引用类型属性共享问题。</li></ul><p>缺点 复杂性：实现过程稍显复杂，需要理解 JavaScript 的原型链机制和构造函数调用。</p><p>总结 寄生组合式继承是一种结合了构造函数继承和原型链继承优点的高级继承方式。它在性能和内存利用率上表现优异，是实现 JavaScript 面向对象编程的理想选择。通过合理使用寄生组合式继承，可以构建出高效、可维护的继承结构。</p></div>',1)])])}const m=t(r,[["render",a]]);export{h as __pageData,m as default};
